import six
from abc import abstractproperty, ABCMeta
from pyparsing import *
from ta_tshark_hex_parser.parser_factory import get_hex_parser
from ta_pdml_parser.parser_factory import get_pdml_parser
from ute_common_abstract_core.message import Message


@six.add_metaclass(ABCMeta)
class MessageParser(object):
    '''
    Interface that all specific parsers connected to MessageSource should fulfill
    '''

    @abstractproperty
    def parse(self, payload):
        '''
        Abstract method for parsing given payload to python structure

        :param payload: data be parsed
        :return: message payload as python structure (dict)
        '''
        pass


class TsharkMessageParser(MessageParser):
    '''
      Extends asn_value2python parser from ta_pdml_parser to be able to parse tshark output.
      '''

    def __init__(self, tshark_pdml_parser):
        self.parser = tshark_pdml_parser

    def parse(self, unparsed_message):
        '''
        Parses given payload to python structure

        :param payload: data be parsed (fragment of the tshark stream capture)
        :return: message payload as python structure (dict)
        '''
        converted_msg_structure = self.parser.get_converted_msg(unparsed_message.msg_payload)
        return Message(converted_msg_structure, unparsed_message.meta_data)


class TsharkHexMessageParser(MessageParser):
    '''
      Extends asn_value2python parser from ta_pdml_parser to be able to parse tshark output.
      '''

    def __init__(self, source_description):
        self.parser = get_hex_parser(source_description)

    def parse(self, unparsed_message):
        '''
        Parses given payload to python structure

        :param data_record: data be parsed (fragment of the tshark stream capture)
        :return: message payload as python structure (dict)
        '''
        return self.parser.get_parsed_msg(unparsed_message.meta_data)


class UesimHexMessageParser(MessageParser):
    '''

    '''
    def __init__(self):
        self.parser = get_pdml_parser()

    def parse(self, unparsed_message):
        '''
        Parses given payload to python structure

        :param data_record: data be parsed (fragment of the tshark stream capture)
        :return: message payload as python structure (dict)
        '''
        exceptional_mapping = {'XNAP-PDU': 'XnAP-PDU'}
        protocol = str(unparsed_message.protocol).lower()
        pdu_type = "{}-{}".format(protocol.upper(), 'PDU')
        pdu_type = pdu_type if pdu_type not in exceptional_mapping else exceptional_mapping[pdu_type]
        hex = unparsed_message.msg_payload
        parsed_asn = self.parser.parse_container(protocol, pdu_type, hex)
        return Message(parsed_asn, unparsed_message.meta_data)


class EgateMessageParser(MessageParser):
    '''
    Extends asn_value2python parser from ta_pdml_parser to be able to parse EGATE output.
    '''
    def __init__(self):
        from ta_pdml_parser import parser_factory
        self._parser = parser_factory.get_pdml_parser()
        ESC = Literal('\x1b')
        integer = Word(nums)
        self.escapeSeq = Combine(ESC + '[' + Optional(delimitedList(integer, ';')) + oneOf(list(alphas)))

    def get_rid_of_vt100(self, payload):
        '''
        Adds suppressing of "[K" character sequence

        :param payload: data be parsed
        :return: corrected payload
        '''
        return Suppress(self.escapeSeq).transformString(payload)

    def parse(self, unparsed_message):
        '''
        Parses given payload to python structure

        :param payload: data be parsed (fragment of the EGATE stream capture on telnet connection)
        :return: message payload as python structure (dict)
        '''
        payload = self.get_rid_of_vt100(unparsed_message.msg_payload)
        payload = "\n" + payload  # WA for pdml parser error
        parsed_payload = self._parser._convert_asn_value2pythons_structure(payload)
        return Message(parsed_payload, unparsed_message.meta_data)


